import { Menu } from 'lucide-react'
import type { ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './header.module.scss'

export interface HeaderProps {
  title?: ReactNode
  /** Shown on small screens — typically opens the app drawer. */
  onMenuClick?: () => void
  /** Hide the menu button entirely. */
  showMenuButton?: boolean
  actions?: ReactNode
  /** Leading slot (logo, back button) — replaces the menu button when set. */
  leading?: ReactNode
  /** Subtitle under the title. */
  description?: ReactNode
  sticky?: boolean
  className?: string
  /** Accessible name when the title is not a string. */
  'aria-label'?: string
}

/** Page header: optional menu trigger, title, description and trailing actions. */
export function Header({
  title = 'Dashboard',
  onMenuClick,
  showMenuButton = true,
  actions,
  leading,
  description,
  sticky = true,
  className,
  'aria-label': ariaLabel,
}: HeaderProps) {
  return (
    <header
      aria-label={ariaLabel}
      className={cx(styles.root, sticky && styles.sticky, className)}
    >
      {leading ??
        (showMenuButton && onMenuClick ? (
          <button
            type="button"
            className={cx(styles.menu, styles.menuAuto)}
            onClick={onMenuClick}
            aria-label="Open menu"
          >
            <Menu aria-hidden />
          </button>
        ) : null)}

      <div className={styles.titleWrap}>
        <h1 className={styles.title}>{title}</h1>
        {description ? <p className={styles.description}>{description}</p> : null}
      </div>

      {actions ? <div className={styles.actions}>{actions}</div> : null}
    </header>
  )
}

@use 'styles' as vz;

.root {
  position: relative;
  z-index: vz.z('sticky');
  display: flex;
  height: 3.75rem;
  flex: none;
  align-items: center;
  gap: vz.space(3);
  padding-inline: vz.space(4);
  border-bottom: 1px solid vz.color('border');
  background: vz.color('card', 0.9);
  backdrop-filter: blur(16px) saturate(180%);
}

.sticky {
  position: sticky;
  top: 0;
}

.menu {
  display: inline-flex;
  width: vz.space(10);
  height: vz.space(10);
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: vz.radius('md');
  background: transparent;
  color: vz.color('foreground');
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent');
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  svg {
    @include vz.icon(5);
  }
}

.title-wrap {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-size: vz.font-size('base');
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;

  @include vz.truncate;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: 0.6875rem;
  line-height: 1.35;

  @include vz.truncate;
}

.actions {
  display: flex;
  flex: none;
  align-items: center;
  gap: vz.space(2);
}

@include vz.up('sm') {
  .root {
    padding-inline: vz.space(5);
  }

  .title {
    font-size: vz.font-size('lg');
  }

  .description {
    font-size: vz.font-size('xs');
  }
}

@include vz.up('lg') {
  .menu-auto {
    display: none;
  }
}
